<?php
declare(strict_types=1);
$news = is_array($news ?? null) ? $news : [];
$pagination = is_array($pagination ?? null) ? $pagination : [];
$page = (int) ($pagination['page'] ?? 1);
$pages = (int) ($pagination['pages'] ?? 1);
?>
<section class="section bg-light-section"><div class="container py-5"><div class="text-center mb-5"><p class="eyebrow text-brand">Actualidad</p><h1>Noticias y artículos</h1></div><div class="row g-4"><?php foreach ($news as $article): ?><div class="col-lg-4 col-md-6"><article class="card h-100 border-0 shadow-sm"><?php $cover = media_url((int) ($article['cover_media_id'] ?? 0), 700); ?><?php if ($cover !== null): ?><img src="<?= e($cover) ?>" class="card-img-top" alt="<?= e((string) $article['title']) ?>" style="height:220px;object-fit:cover;"><?php endif; ?><div class="card-body d-flex flex-column"><small class="text-muted"><?= e((string) ($article['category'] ?? 'Noticias')) ?> · <?= e((string) ($article['published_at'] ?? '')) ?></small><h2 class="h4 mt-2"><?= e((string) $article['title']) ?></h2><p class="text-muted flex-grow-1"><?= e((string) ($article['summary'] ?? '')) ?></p><a class="btn bg-brand text-white" href="<?= e(url('noticias/' . $article['slug'])) ?>">Leer noticia</a></div></article></div><?php endforeach; ?></div><?php if ($pages > 1): ?><nav class="mt-5" aria-label="Páginas de noticias"><ul class="pagination justify-content-center"><?php for ($number = 1; $number <= $pages; $number++): ?><li class="page-item <?= $number === $page ? 'active' : '' ?>"><a class="page-link" href="<?= e(url('noticias?page=' . $number)) ?>"><?= $number ?></a></li><?php endfor; ?></ul></nav><?php endif; ?><?php if ($news === []): ?><p class="text-center text-muted">Todavía no hay noticias publicadas.</p><?php endif; ?></div></section>